{"command":"$ErrorActionPreference = 'Stop'
$cases = @(
  @{ practiceType='listening'; subtype='picture-description'; difficulty='easy'; count=1; tags=@('smoke','picture') },
  @{ practiceType='listening'; subtype='question-response'; difficulty='medium'; count=1; tags=@('smoke','response') },
  @{ practiceType='listening'; subtype='short-conversation'; difficulty='medium'; count=1; tags=@('smoke','conversation') },
  @{ practiceType='listening'; subtype='short-talk'; difficulty='hard'; count=1; tags=@('smoke','talk') },
  @{ practiceType='grammar'; subtype='sentence-completion'; difficulty='easy'; count=1; tags=@('smoke','grammar'); grammarPoint='时态' },
  @{ practiceType='grammar'; subtype='part-of-speech'; difficulty='medium'; count=1; tags=@('smoke','grammar'); grammarPoint='词性' },
  @{ practiceType='grammar'; subtype='tense-voice'; difficulty='medium'; count=1; tags=@('smoke','grammar'); grammarPoint='时态 / 语态' },
  @{ practiceType='grammar'; subtype='preposition-conjunction'; difficulty='hard'; count=1; tags=@('smoke','grammar'); grammarPoint='介词 / 连词' },
  @{ practiceType='grammar'; subtype='business-context'; difficulty='hard'; count=1; tags=@('smoke','grammar'); grammarPoint='商务语境' }
)
$results = @()
foreach ($case in $cases) {
  $body = $case | ConvertTo-Json -Depth 5
  $started = Get-Date
