    $elapsed = [math]::Round(((Get-Date) - $started).TotalSeconds, 1)
    $json = $response.Content | ConvertFrom-Json
    $q = $json.data.questions[0]
    $optionKeys = @($q.options.PSObject.Properties.Name | Sort-Object)
    $fieldProblems = @()
    if (-not $json.ok) { $fieldProblems += 'ok=false' }
    if ($json.data.questions.Count -ne 1) { $fieldProblems += "count=$($json.data.questions.Count)" }
    if (-not $q.id) { $fieldProblems += 'missing id' }
    if ($q.type -ne $case.practiceType) { $fieldProblems += "type=$($q.type)" }
    if (-not $q.subtype) { $fieldProblems += 'missing subtype' }
    if (-not $q.prompt) { $fieldProblems += 'missing prompt' }
    if (($optionKeys -join ',') -ne 'A,B,C,D') { $fieldProblems += "options=$($optionKeys -join ',')" }
    if (@('A','B','C','D') -notcontains $q.answer) { $fieldProblems += "answer=$($q.answer)" }
    if (-not $q.explanationZh) { $fieldProblems += 'missing explanationZh' }
    if ($case.practiceType -eq 'listening' -and -not $q.listeningScript) { $fieldProblems += 'missing listeningScript' }
    if ($case.practiceType -eq 'grammar' -and -not $q.grammarPoint) { $fieldProblems += 'missing grammarPoint' }
    $results += [pscustomobject]@{
      type=$case.practiceType
      subtype=$case.subtype
      http=$response.StatusCode
      ok=$json.ok
      seconds=$elapsed
      id=($q.id -as [string])
      returnedSubtype=($q.subtype -as [string])
      answer=($q.answer -as [string])
      promptPreview=(($q.prompt -as [string]) -replace "`r|`n", ' ').Substring(0, [Math]::Min(80, (($q.prompt -as [string]).Length)))
      status= if ($fieldProblems.Count -eq 0) { 'PASS' } else { 'FAIL: ' + ($fieldProblems -join '; ') }
    }
