import { NextResponse } from "next/server";

import { AppError, isAppError } from "@/lib/errors";
import { recordPracticeAnswer } from "@/lib/practice-service";

function jsonError(error: AppError) {
  return NextResponse.json(
    {
      ok: false,
      error: {
        code: error.code,
        message: error.message,
      },
    },
    { status: error.status },
  );
}

export async function POST(request: Request) {
  try {
    const body = (await request.json()) as Record<string, unknown>;
    const questionId =
      typeof body.questionId === "string" ? body.questionId.trim() : "";
    const userAnswer =
      typeof body.userAnswer === "string" ? body.userAnswer.trim() : "";
    const timeSpentSeconds =
      typeof body.timeSpentSeconds === "number" ? body.timeSpentSeconds : 0;

    if (!questionId || !userAnswer) {
      throw new AppError(
        "REQUEST_INVALID",
        "题目 ID 和用户答案不能为空。",
        400,
      );
    }

    const data = await recordPracticeAnswer({
      questionId,
      userAnswer,
      timeSpentSeconds,
    });

    return NextResponse.json({ ok: true, data });
  } catch (error) {
    if (isAppError(error)) {
      return jsonError(error);
    }

    return jsonError(
      new AppError("DATABASE_WRITE_FAILED", "保存答题记录失败。", 500),
    );
  }
}

import { AppError } from "@/lib/errors";
import { createOrUpdateMistake } from "@/lib/mistake-service";
import { prisma } from "@/lib/prisma";

export type PracticeAnswerInput = {
  questionId: string;
  userAnswer: string;
  timeSpentSeconds?: number;
};

function normalizeAnswer(answer: string) {
  return answer.trim().toUpperCase();
}

export async function recordPracticeAnswer(input: PracticeAnswerInput) {
  const userAnswer = normalizeAnswer(input.userAnswer);

  if (!["A", "B", "C", "D"].includes(userAnswer)) {
    throw new AppError(
      "REQUEST_INVALID",
      "用户答案必须是 A、B、C 或 D。",
      400,
    );
  }

  const question = await prisma.question.findUnique({
    where: { id: input.questionId },
  });

  if (!question) {
    throw new AppError("REQUEST_INVALID", "题目不存在。", 404);
  }

  const isCorrect = question.answer === userAnswer;

  const practiceRecord = await prisma.practiceRecord.create({
    data: {
      questionId: question.id,
      practiceType: question.type,
      userAnswer,
      isCorrect,
      timeSpentSeconds: Math.max(0, input.timeSpentSeconds ?? 0),
    },
  });

  const mistake = isCorrect
    ? null
    : await createOrUpdateMistake(question.id);

  return {
    practiceRecord,
    mistake,
    result: {
      questionId: question.id,
      userAnswer,
      correctAnswer: question.answer,
      isCorrect,
      explanationZh: question.explanationZh,
      options: JSON.parse(question.optionsJson) as Record<string, string>,
      tags: JSON.parse(question.tagsJson) as string[],
      listeningScript: question.listeningScript,
      grammarPoint: question.grammarPoint,
    },
  };
}

