    if (status !== "active") {
      params.set("status", status);
    }

    if (tag.trim()) {
      params.set("tag", tag.trim());
    }

    return params.toString();
  }, [status, tag, type]);

  async function loadMistakes() {
    setLoading(true);
    setError(null);

    try {
      const response = await fetch(`/api/mistakes${query ? `?${query}` : ""}`, {
