      }
    } else {
      [pscustomobject]@{ name=$check.name; http='ERR'; ok=$false; count=0; code=''; status='FAIL: ' + $_.Exception.Message }
    }
  }
}
$results | Format-Table -AutoSize | Out-String -Width 160","workdir":"E:\托业","timeout_ms":120000}

