{"command":"@'
import { PrismaClient } from '@prisma/client';
const prisma = new PrismaClient();
const baseUrl = 'http://127.0.0.1:3000';
const answers = ['A', 'B', 'C', 'D'];
const question = await prisma.question.findFirst({ orderBy: { createdAt: 'desc' } });
if (!question) throw new Error('No question available for retry smoke.');
const wrongAnswer = answers.find((answer) => answer !== question.answer);
async function postAnswer(userAnswer) {
  const response = await fetch(`${baseUrl}/api/practice-records`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ questionId: question.id, userAnswer, timeSpentSeconds: 0 }),
  });
  const payload = await response.json();
  if (!response.ok || !payload.ok) throw new Error(payload.error?.message || response.statusText);
  return payload.data;
}
const before = await prisma.mistake.findUnique({ where: { questionId: question.id } });
const wrongResult = await postAnswer(wrongAnswer);
const afterWrong = await prisma.mistake.findUnique({ where: { questionId: question.id } });
const correctResult = await postAnswer(question.answer);
const afterCorrect = await prisma.mistake.findUnique({ where: { questionId: question.id } });
console.table([
  {
    step: 'wrong retry',
    isCorrect: wrongResult.result.isCorrect,
    userAnswer: wrongResult.result.userAnswer,
    correctAnswer: wrongResult.result.correctAnswer,
    wrongCountBefore: before?.wrongCount ?? 0,
    wrongCountAfter: afterWrong?.wrongCount ?? 0,
    statusAfter: afterWrong?.status ?? '',
    pass: wrongResult.result.isCorrect === false && Boolean(afterWrong) && (afterWrong.wrongCount > (before?.wrongCount ?? 0)) && afterWrong.status === 'reviewing',
  },
  {
    step: 'correct retry',
    isCorrect: correctResult.result.isCorrect,
    userAnswer: correctResult.result.userAnswer,
    correctAnswer: correctResult.result.correctAnswer,
    wrongCountBefore: afterWrong?.wrongCount ?? 0,
    wrongCountAfter: afterCorrect?.wrongCount ?? 0,
    statusAfter: afterCorrect?.status ?? '',
    pass: correctResult.result.isCorrect === true && afterCorrect?.wrongCount === afterWrong?.wrongCount,
  },
]);
await prisma.$disconnect();
'@ | npx tsx -","workdir":"E:\托业","timeout_ms":120000}

