import { BarChart3, TrendingUp } from "lucide-react";

import { MetricCard } from "@/components/metric-card";
import { Badge } from "@/components/ui/badge";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { getStats } from "@/lib/stats-service";

export const dynamic = "force-dynamic";

export default async function StatsPage() {
  const stats = await getStats();

  const summary = [
    { label: "今日练习", value: stats.todayCount, unit: "题" },
    { label: "总练习", value: stats.totalCount, unit: "题" },
    { label: "总正确率", value: stats.totalAccuracy, unit: "%" },
    { label: "当前错题", value: stats.activeMistakeCount, unit: "待复习" },
    { label: "听力正确率", value: stats.listeningAccuracy, unit: "%" },
    { label: "语法正确率", value: stats.grammarAccuracy, unit: "%" },
    { label: "已掌握错题", value: stats.masteredMistakeCount, unit: "题" },
  ];

  return (
    <div className="space-y-6">
      <section className="space-y-3">
        <Badge variant="outline" className="gap-1.5">
          <BarChart3 className="size-3.5" />
          Gate 4 / T12
        </Badge>
        <div>
          <h1 className="text-3xl font-semibold tracking-normal md:text-5xl">
            学习统计
          </h1>
          <p className="mt-3 max-w-2xl text-base leading-7 text-muted-foreground">
            统计直接从练习记录和错题记录计算，保持本机数据一致。
          </p>
        </div>
      </section>

      <section className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        {summary.map((item) => (
          <MetricCard
            key={item.label}
            label={item.label}
            value={item.value}
            unit={item.unit}
          />
        ))}
      </section>

      <div className="grid gap-4 lg:grid-cols-[1.4fr_1fr]">
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <TrendingUp className="size-5" />
