import {
  Area,
  AreaChart,
  CartesianGrid,
  Legend,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from "recharts";
import {
  Award,
  BarChart3,
  BookOpenCheck,
  CheckCircle2,
  Flame,
  Headphones,
  NotebookTabs,
  Sparkles,
  Target,
  TrendingUp,
} from "lucide-react";

import { Badge } from "@/components/ui/badge";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { cn } from "@/lib/utils";

type StatsData = {
  todayCount: number;
  todayAccuracy: number;
  totalCount: number;
  totalAccuracy: number;
  listeningAccuracy: number;
  grammarAccuracy: number;
  activeMistakeCount: number;
  masteredMistakeCount: number;
  last7Days: Array<{
    date: string;
    count: number;
    correct: number;
  }>;
  weakTags: Array<{
    label: string;
    count: number;
  }>;
};

type StatCardTone = "green" | "mint" | "amber" | "sky" | "lime";

type StatCardItem = {
  label: string;
  value: number;
  unit: string;
  helper: string;
  tone: StatCardTone;
  icon: React.ComponentType<{ className?: string }>;
  progress?: number;
  badge?: string;
};

const toneStyles: Record<
  StatCardTone,
  {
    card: string;
    icon: string;
    accent: string;
    bar: string;
  }
> = {
  green: {
    card: "from-emerald-50 via-teal-50 to-white border-emerald-100",
    icon: "bg-emerald-100 text-emerald-700",
    accent: "text-emerald-900",
    bar: "bg-emerald-500",
  },
  mint: {
    card: "from-teal-50 via-cyan-50 to-white border-teal-100",
    icon: "bg-teal-100 text-teal-700",
    accent: "text-teal-900",
    bar: "bg-teal-500",
  },
  amber: {
    card: "from-amber-50 via-orange-50 to-white border-amber-100",
    icon: "bg-amber-100 text-amber-700",
    accent: "text-amber-950",
    bar: "bg-amber-500",
  },
  sky: {
    card: "from-sky-50 via-cyan-50 to-white border-sky-100",
    icon: "bg-sky-100 text-sky-700",
    accent: "text-sky-950",
    bar: "bg-sky-500",
  },
  lime: {
    card: "from-lime-50 via-emerald-50 to-white border-lime-100",
    icon: "bg-lime-100 text-lime-700",
    accent: "text-lime-950",
    bar: "bg-lime-500",
  },
};

function formatDateLabel(date: string) {
  const [, month, day] = date.split("-");
  return `${month}/${day}`;
}

function CircleMeter({ value, tone }: { value: number; tone: StatCardTone }) {
  const radius = 20;
  const circumference = 2 * Math.PI * radius;
  const offset = circumference - (Math.min(Math.max(value, 0), 100) / 100) * circumference;

  return (
    <div className="relative size-14">
      <svg className="-rotate-90" viewBox="0 0 52 52" aria-hidden="true">
        <circle
          cx="26"
          cy="26"
          r={radius}
          fill="none"
          stroke="rgba(15, 23, 42, 0.08)"
          strokeWidth="6"
        />
        <circle
          cx="26"
          cy="26"
          r={radius}
          fill="none"
          stroke="currentColor"
          strokeDasharray={circumference}
          strokeDashoffset={offset}
          strokeLinecap="round"
          strokeWidth="6"
          className={toneStyles[tone].accent}
        />
      </svg>
      <span className="absolute inset-0 flex items-center justify-center text-xs font-semibold text-emerald-950">
        {value}%
      </span>
    </div>
  );
}

function StatsMascot() {
  return (
