const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');
(async () => {
  const outDir = path.resolve('output/playwright');
  fs.mkdirSync(outDir, { recursive: true });
  const browser = await chromium.launch({ channel: 'msedge', headless: true });
  const results = [];
  const labels = {
    title: '\u5b66\u4e60\u7edf\u8ba1',
    weekly: '\u6700\u8fd17\u5929',
    weak: '\u8584\u5f31\u6807\u7b7e',
    today: '\u4eca\u65e5\u7ec3\u4e60',
    currentMistake: '\u5f53\u524d\u9519\u9898'
  };
  for (const viewport of [
    { name: 'desktop', width: 1440, height: 1000 },
    { name: 'mobile', width: 390, height: 900 },
  ]) {
    const page = await browser.newPage({ viewport });
    const consoleErrors = [];
    page.on('console', (msg) => { if (msg.type() === 'error') consoleErrors.push(msg.text()); });
    await page.goto('http://127.0.0.1:3000/stats', { waitUntil: 'networkidle' });
    await page.screenshot({ path: path.join(outDir, `v1-7-stats-${viewport.name}.png`), fullPage: true });
    const visibility = {};
    for (const [key, label] of Object.entries(labels)) {
      visibility[key] = await page.getByText(label).first().isVisible().catch(() => false);
    }
    const chartSvgCount = await page.locator('.recharts-wrapper svg').count();
    const overflowCandidates = await page.evaluate(() => {
      const width = document.documentElement.clientWidth;
      return Array.from(document.querySelectorAll('body *')).filter((el) => {
        const rect = el.getBoundingClientRect();
        return rect.width > 0 && (rect.left < -1 || rect.right > width + 1);
      }).slice(0, 8).map((el) => ({ tag: el.tagName, text: (el.textContent || '').trim().slice(0, 40), className: String(el.className).slice(0, 80) }));
    });
    results.push({ viewport: viewport.name, visibility, chartSvgCount, overflowCandidates, consoleErrors });
    await page.close();
  }
  await browser.close();
  console.log(JSON.stringify(results, null, 2));
})();
