if (-not (Test-Path $cloudflared)) { throw 'cloudflared.exe not found' }

$outFile = Join-Path $PWD 'output\cloudflared-acceptance.out.log'
$errFile = Join-Path $PWD 'output\cloudflared-acceptance.err.log'
New-Item -ItemType Directory -Force -Path (Split-Path $outFile) | Out-Null
Remove-Item -Force -ErrorAction SilentlyContinue $outFile,$errFile

$args = @('tunnel','--no-autoupdate','--edge-ip-version','4','--protocol','http2','--url','http://127.0.0.1:3000')
$p = Start-Process -FilePath $cloudflared -ArgumentList $args -NoNewWindow -PassThru -RedirectStandardOutput $outFile -RedirectStandardError $errFile
try {
  $url = $null
  $deadline = (Get-Date).AddSeconds(45)
  while ((Get-Date) -lt $deadline -and -not $p.HasExited) {
    Start-Sleep -Milliseconds 800
    $text = ''
    if (Test-Path $outFile) { $text += Get-Content -Raw -ErrorAction SilentlyContinue $outFile }
    if (Test-Path $errFile) { $text += "`n" + (Get-Content -Raw -ErrorAction SilentlyContinue $errFile) }
    $m = [regex]::Match($text, 'https://[a-zA-Z0-9-]+\.trycloudflare\.com')
    if ($m.Success) { $url = $m.Value; break }
    if ($text -match 'status_code=500|Unauthorized: Tunnel not found|Failed to request quick Tunnel|error unmarshalling') {
      Write-Host 'EARLY_LOG_ERROR_DETECTED'
      break
    }
  }

  if (-not $url) {
    $combined = ''
    if (Test-Path $outFile) { $combined += Get-Content -Raw -ErrorAction SilentlyContinue $outFile }
    if (Test-Path $errFile) { $combined += "`n" + (Get-Content -Raw -ErrorAction SilentlyContinue $errFile) }
    Write-Host 'TUNNEL_URL_NOT_FOUND'
    Write-Host ($combined -split "`n" | Select-Object -Last 25)
    exit 2
  }

  Write-Host "TUNNEL_URL=$url"
  Start-Sleep -Seconds 3
  $public = Invoke-WebRequest -Uri $url -UseBasicParsing -TimeoutSec 20
  Write-Host "PUBLIC status=$($public.StatusCode) length=$($public.Content.Length)"
  if ($public.Content -match 'TOEIC Practice Studio') { Write-Host 'PUBLIC_CONTENT_OK' } else { Write-Host 'PUBLIC_CONTENT_UNKNOWN' }
} finally {
  if ($p -and -not $p.HasExited) {
    Stop-Process -Id $p.Id -Force -ErrorAction SilentlyContinue
    Write-Host "STOPPED cloudflared pid=$($p.Id)"
  }
